SELECT r.sequence, r.id, r.archived, r.conversation_id, r.turn_id, r.created_at, r.updated_at, r.created_by_user_id, r.mode, r.role, r.status, r.type, r.content, r.raw_content, r.summary, r.context_summary, r.embedding_index, r.tags, r.interim, r.elicitation_id, r.parent_message_id, r.superseded_by, r.linked_conversation_id, r.tool_name, r.preamble, r.iteration, r.phase, r.attachment_payload_id, r.elicitation_payload_id FROM (SELECT data_rows.id, data_rows.should_delete, data_rows.archived, data_rows.conversation_id, data_rows.turn_id, data_rows.sequence, data_rows.created_at, data_rows.updated_at, data_rows.created_by_user_id, data_rows.mode, data_rows.role, data_rows.status, data_rows.type, data_rows.content, data_rows.raw_content, data_rows.summary, data_rows.context_summary, data_rows.embedding_index, data_rows.tags, data_rows.interim, data_rows.elicitation_id, data_rows.parent_message_id, data_rows.superseded_by, data_rows.linked_conversation_id, data_rows.tool_name, data_rows.preamble, data_rows.iteration, data_rows.phase, data_rows.attachment_payload_id, data_rows.elicitation_payload_id FROM  (SELECT 0 AS should_delete, `id`, `archived`, `conversation_id`, `turn_id`, `sequence`, `created_at`, `updated_at`, `created_by_user_id`, `mode`, `role`, `status`, `type`, `content`, `raw_content`, `summary`, `context_summary`, `embedding_index`, `tags`, `interim`, `elicitation_id`, `parent_message_id`, `superseded_by`, `linked_conversation_id`, `tool_name`, `preamble`, `iteration`, `phase`, `attachment_payload_id`, `elicitation_payload_id` FROM message)  data_rows) r WHERE $criteria.CompositeIn("r", $WriterKeys)